package com.roothack.overlord.runtime;
import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;
public final class Access{
 private static final Map<String,Method> methods=new ConcurrentHashMap<>();private static final Map<String,Class<?>> types=new ConcurrentHashMap<>();
 public static Class<?> type(String name)throws Exception{Class<?> t=types.get(name);if(t==null){t=Class.forName(name);types.put(name,t);}return t;}
 public static Object field(Object o,String n)throws Exception{Class<?> t=o instanceof Class?(Class<?>)o:o.getClass();for(Class<?> c=t;c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(n);f.setAccessible(true);return f.get(o instanceof Class?null:o);}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(t+"."+n);}
 public static Object call(Object o,String n,Object...a)throws Exception{Class<?> c=o instanceof Class?(Class<?>)o:o.getClass();String key=c.getName()+n+Arrays.toString(Arrays.stream(a).map(v->v==null?null:v.getClass().getName()).toArray());Method m=methods.get(key);if(m==null){outer:for(Method candidate:c.getMethods()){if(!candidate.getName().equals(n)||candidate.getParameterCount()!=a.length)continue;Class<?>[] ps=candidate.getParameterTypes();for(int i=0;i<ps.length;i++)if(a[i]!=null&&!box(ps[i]).isInstance(a[i]))continue outer;m=candidate;break;}if(m==null)throw new NoSuchMethodException(key);m.trySetAccessible();methods.put(key,m);}try{return m.invoke(o instanceof Class?null:o,a);}catch(InvocationTargetException e){throw new Exception(n+": "+e.getCause(),e.getCause());}}
 private static Class<?> box(Class<?> c){if(!c.isPrimitive())return c;if(c==int.class)return Integer.class;if(c==boolean.class)return Boolean.class;if(c==float.class)return Float.class;if(c==double.class)return Double.class;if(c==long.class)return Long.class;return c;}
 public static Object make(String name,Object...a)throws Exception{outer:for(var c:type(name).getConstructors()){if(c.getParameterCount()!=a.length)continue;var p=c.getParameterTypes();for(int i=0;i<p.length;i++)if(a[i]!=null&&!box(p[i]).isInstance(a[i]))continue outer;return c.newInstance(a);}throw new NoSuchMethodException(name);}
 public static Object mc()throws Exception{return call(type("net.minecraft.class_310"),"method_1551");}public static Object player()throws Exception{return field(mc(),"field_1724");}public static Object world()throws Exception{return field(mc(),"field_1687");}
 public static int num(Object o,String n)throws Exception{return ((Number)call(o,n)).intValue();}public static double real(Object o,String n,Object...a)throws Exception{return ((Number)call(o,n,a)).doubleValue();}
 public static Object pos(int x,int y,int z)throws Exception{return make("net.minecraft.class_2338",x,y,z);}public static Object state(int x,int y,int z)throws Exception{return call(world(),"method_8320",pos(x,y,z));}
 public static String id(Object stack)throws Exception{if((Boolean)call(stack,"method_7960"))return "air";return call(field(type("net.minecraft.class_7923"),"field_41178"),"method_10221",call(stack,"method_7909")).toString().replace("minecraft:","");}
 public static String block(int x,int y,int z)throws Exception{return call(field(type("net.minecraft.class_7923"),"field_41175"),"method_10221",call(state(x,y,z),"method_26204")).toString().replace("minecraft:","");}
 public static boolean air(int x,int y,int z)throws Exception{return (Boolean)call(state(x,y,z),"method_45474");}
 public static String dimension()throws Exception{return call(call(world(),"method_27983"),"method_29177").toString();}
 public static Object inv()throws Exception{return call(player(),"method_31548");}
 public static Map<String,Integer> counts()throws Exception{Map<String,Integer> result=new HashMap<>();Object inv=inv();for(int i=0;i<36;i++){Object s=call(inv,"method_5438",i);if(!(Boolean)call(s,"method_7960"))result.merge(id(s),num(s,"method_7947"),Integer::sum);}Object h=field(player(),"field_7498");for(int i=5;i<=8;i++){Object s=call(call(h,"method_7611",i),"method_7677");if(!(Boolean)call(s,"method_7960"))result.merge(id(s),num(s,"method_7947"),Integer::sum);}return result;}
 public static boolean enchanted(String id)throws Exception{for(int i=0;i<36;i++){Object s=call(inv(),"method_5438",i);if(id(s).equals(id)&&(Boolean)call(s,"method_7942"))return true;}Object h=field(player(),"field_7498");for(int i=5;i<=8;i++){Object s=call(call(h,"method_7611",i),"method_7677");if(id(s).equals(id)&&(Boolean)call(s,"method_7942"))return true;}return false;}
 public static void close()throws Exception{if(field(mc(),"field_1755")!=null)call(player(),"method_7346");}
 public static void message(String text){try{call(player(),"method_7353",call(type("net.minecraft.class_2561"),"method_43470","[Overlord] "+text),false);}catch(Exception e){System.out.println("[Overlord] "+text);}}
 public static Object command(String kind,Object goal)throws Exception{return make("baritone.api.process.PathingCommand",goal,field(type("baritone.api.process.PathingCommandType"),kind));}
}
